package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func main() {
	// Check arguments
	if len(os.Args) < 5 {
		fmt.Println("Usage: go-ast-differ <repoUrl> <localRepoPath> <branchName> <currentCommit> [outputPath]")
		os.Exit(1)
	}

	repoURL := os.Args[1]
	localRepoPath := os.Args[2]
	branchName := os.Args[3]
	currentCommit := os.Args[4]

	// Set default output path if not provided
	outputPath := "./"
	if len(os.Args) >= 6 {
		outputPath = os.Args[5]
	}

	// Clone repository if it doesn't exist
	cloneRepo(repoURL, branchName, localRepoPath)

	// Get changed files between commits
	changedFiles, err := getChangedFiles(branchName, localRepoPath)
	if err != nil {
		fmt.Printf("Error getting changed files: %v\n", err)
		os.Exit(1)
	}

	// Get lists of new and deleted files
	newFiles, _ := getNewFiles(branchName, currentCommit, localRepoPath)
	deletedFiles, _ := getDeletedFiles(branchName, currentCommit, localRepoPath)

	// Create maps for quick lookup
	newFileMap := make(map[string]bool)
	deletedFileMap := make(map[string]bool)

	for _, file := range newFiles {
		newFileMap[file] = true
		fmt.Printf("New file detected: %s\n", file)
	}

	for _, file := range deletedFiles {
		deletedFileMap[file] = true
		fmt.Printf("Deleted file detected: %s\n", file)
	}

	fmt.Printf("Modified files: %v\n", changedFiles)

	// Filter only Go files
	var goFiles []string
	for _, file := range changedFiles {
		if strings.HasSuffix(file, ".go") {
			goFiles = append(goFiles, file)
		}
	}

	if len(goFiles) == 0 {
		fmt.Println("No Go files were modified between the specified commits")
		os.Exit(0)
	}

	// First checkout the branch to ensure we're starting from the right point
	checkoutCmd := exec.Command("git", "checkout", branchName)
	checkoutCmd.Dir = localRepoPath
	branchOutput, err := checkoutCmd.CombinedOutput()
	if err != nil {
		fmt.Printf("Error checking out branch %s: %v\nOutput: %s\n",
			branchName, err, string(branchOutput))

		// Try alternative approaches - this might be a detached HEAD or a remote branch
		fmt.Println("Trying alternative checkout approaches...")

		// Try to checkout the commit directly
		checkoutCmd = exec.Command("git", "checkout", branchName+"^{commit}")
		checkoutCmd.Dir = localRepoPath
		output, err := checkoutCmd.CombinedOutput()
		if err != nil {
			fmt.Printf("Error checking out commit directly: %v\nOutput: %s\n", err, string(output))
			os.Exit(1)
		}
		fmt.Println("Successfully checked out commit directly.")
	}

	allChanges := processGoFiles(goFiles, localRepoPath, branchName, currentCommit, newFileMap, deletedFileMap)

	createOutputFiles(allChanges, outputPath)

	getGranularChangeForFunctions(goFiles, localRepoPath, outputPath)

	fmt.Println("AST diff complete. Check output files for details.")
}

package main

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// cloneRepo clones a Git repository if it doesn't exist locally
func cloneRepo(repoURL, branchName, localPath string) {
	_, err := os.Stat(localPath)
	if os.IsNotExist(err) {
		fmt.Printf("Cloning repository %s to %s\n", repoURL, localPath)
		cmd := exec.Command("git", "clone", repoURL, localPath)
		output, err := cmd.CombinedOutput()
		if err != nil {
			fmt.Printf("Error cloning repository: %v\nOutput: %s\n", err, string(output))
			os.Exit(1)
		}
	} else {
		fmt.Println("Repository already cloned.")

		// Fetch the latest changes
		cmd2 := exec.Command("git", "branch", "--all")
		cmd2.Env = os.Environ()
		output2, err := cmd2.CombinedOutput()
		if err != nil {
			fmt.Printf("Warning: Failed to fetch latest changes: %v\nOutput: %s\n",
				err, string(output2))
		} else {
			fmt.Printf("Successfully fetched all branches \n %v", string(output2))
		}

		cmd1 := exec.Command("git", "remote", "set-url", "origin", repoURL)
		cmd1.Env = os.Environ()
		output1, err := cmd1.CombinedOutput()
		if err != nil {
			fmt.Printf("Warning: Failed to fetch latest changes: %v\nOutput: %s\n",
				err, string(output1))
		} else {
			fmt.Println("Successfully set origin remote url")
		}

		// Fetch the latest changes
		cmd := exec.Command("git", "fetch")
		cmd.Env = os.Environ()
		output, err := cmd.CombinedOutput()
		if err != nil {
			fmt.Printf("Warning: Failed to fetch latest changes: %v\nOutput: %s\n",
				err, string(output))
		} else {
			fmt.Printf("Successfully fetched latest changes. %s", string(output))
		}
	}
}

// getNewFiles returns a list of files that are new in the current commit compared to the branch
func getNewFiles(branchName, newCommit, localPath string) ([]string, error) {
	// List files that are in the new commit but not in the old commit (A = added)
	diffCmd := exec.Command("git", "diff", "--name-only", "--diff-filter=A", branchName, newCommit)
	diffCmd.Env = os.Environ()
	diffCmd.Dir = localPath
	diffBytes, err := diffCmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("error getting new files between %s and %s: %v\nOutput: %s",
			branchName, newCommit, err, string(diffBytes))
	}

	newFiles := strings.Split(strings.TrimSpace(string(diffBytes)), "\n")
	if len(newFiles) == 1 && newFiles[0] == "" {
		return []string{}, nil
	}

	fmt.Printf("Detected %d new files added between %s and %s\n",
		len(newFiles), branchName, newCommit)

	return newFiles, nil
}

func getDeletedFiles(branchName, newCommit, localPath string) ([]string, error) {
	// List files that were in the old commit but not in the new commit (D = deleted)
	diffCmd := exec.Command("git", "diff", "--name-only", "--diff-filter=D", branchName, newCommit)
	diffCmd.Dir = localPath
	diffCmd.Env = os.Environ()
	diffBytes, err := diffCmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("error getting deleted files between %s and %s: %v\nOutput: %s",
			branchName, newCommit, err, string(diffBytes))
	}

	deletedFiles := strings.Split(strings.TrimSpace(string(diffBytes)), "\n")
	if len(deletedFiles) == 1 && deletedFiles[0] == "" {
		return []string{}, nil
	}

	fmt.Printf("Detected %d files deleted between %s and %s\n",
		len(deletedFiles), branchName, newCommit)

	return deletedFiles, nil
}

func getChangedFiles(branchName, localPath string) ([]string, error) {
	diffCmd := exec.Command("git", "diff", "--name-only", branchName)
	diffCmd.Dir = localPath
	diffCmd.Env = os.Environ()
	diffBytes, err := diffCmd.CombinedOutput()
	if err != nil {
		return nil, fmt.Errorf("error getting direct diff for %s: %v\nOutput: %s",
			branchName, err, string(diffBytes))
	}

	changedFiles := strings.Split(strings.TrimSpace(string(diffBytes)), "\n")
	if len(changedFiles) == 1 && changedFiles[0] == "" {
		return []string{}, nil
	}
	return changedFiles, nil
}

