func getGranularChangeForFunctions(goFiles []string, localRepoPath, outputPath string) {
	// Map to store file => function => changes
	granularChanges := make(map[string]map[string]CalledFunctionChanges)
	branchName := os.Args[3]
	currentCommit := strings.TrimSpace(string(os.Args[4]))
	prevCommit := strings.TrimSpace(string(branchName))

	fmt.Printf("Using previous commit: %s\n", prevCommit)
	fmt.Printf("Current commit: %s\n", currentCommit)

	// Step 1: Checkout the previous commit and extract all ASTs
	oldCheckoutCmd := exec.Command("git", "checkout", prevCommit)
	oldCheckoutCmd.Dir = localRepoPath
	oldOutput, err := oldCheckoutCmd.CombinedOutput()
	if err != nil {
		fmt.Printf("Error checking out previous commit %s: %v\nOutput: %s\n",
			prevCommit, err, string(oldOutput))
		return
	}
	fmt.Printf("Checked out previous commit: %s\n", prevCommit)

	// Map to store all ASTs from previous commit
	oldASTs := make(map[string]FileASTData)

	// Process all files in the previous commit
	for _, goFile := range goFiles {
		fullPath := filepath.Join(localRepoPath, goFile)
		fmt.Printf("Processing old AST for: %s\n", fullPath)

		ast, err := extractFileAST(fullPath)
		if err != nil {
			fmt.Printf("Error extracting old AST for %s: %v (file might not exist in old commit)\n", goFile, err)
			// Create an empty AST for files that don't exist in the old commit
			oldASTs[goFile] = createEmptyFileASTData()
			continue
		}
		oldASTs[goFile] = ast
	}

	// Step 2: Checkout the current commit and extract all ASTs
	newCheckoutCmd := exec.Command("git", "checkout", currentCommit)
	newCheckoutCmd.Dir = localRepoPath
	newOutput, err := newCheckoutCmd.CombinedOutput()
	if err != nil {
		fmt.Printf("Error checking out current commit %s: %v\nOutput: %s\n",
			currentCommit, err, string(newOutput))
		return
	}
	fmt.Printf("Checked out current commit: %s\n", currentCommit)

	// Map to store all ASTs from current commit
	newASTs := make(map[string]FileASTData)

	// Process all files in the current commit
	for _, goFile := range goFiles {
		fullPath := filepath.Join(localRepoPath, goFile)
		fmt.Printf("Processing new AST for: %s\n", fullPath)

		ast, err := extractFileAST(fullPath)
		if err != nil {
			fmt.Printf("Error extracting new AST for %s: %v (file might not exist in new commit)\n", goFile, err)
			// Create an empty AST for files that don't exist in the new commit
			newASTs[goFile] = createEmptyFileASTData()
			continue
		}
		newASTs[goFile] = ast
	}

	// Step 3: Analyze functions and methods for all files
	for _, goFile := range goFiles {
		oldAST, oldExists := oldASTs[goFile]
		newAST, newExists := newASTs[goFile]

		// Skip files that don't exist in either commit
		if !oldExists && !newExists {
			continue
		}

		// Handle cases where the file exists only in one commit
		if !oldExists {
			oldAST = createEmptyFileASTData()
		}
		if !newExists {
			newAST = createEmptyFileASTData()
		}

		fileChanges := make(map[string]CalledFunctionChanges)

		// Check regular functions
		for name, oldFunc := range oldAST.Functions {
			if newFunc, exists := newAST.Functions[name]; exists {
				// Function exists in both commits, compare them
				oldCode := formatNode(oldFunc, oldAST.FileSet)
				newCode := formatNode(newFunc, newAST.FileSet)
				if oldCode != newCode {
					// Function has changed, analyze in detail
					changes := compareCalledFunctions(oldFunc, newFunc, oldAST, newAST)
					fileChanges[name] = changes
					fmt.Printf("Added modified function: %s\n", name)
				}
			}
		}

		// Check methods too
		for name, oldMethod := range oldAST.Methods {
			if newMethod, exists := newAST.Methods[name]; exists {
				// Method exists in both commits, compare them
				oldCode := formatNode(oldMethod, oldAST.FileSet)
				newCode := formatNode(newMethod, newAST.FileSet)
				if oldCode != newCode {
					// Method has changed, analyze in detail
					changes := compareCalledFunctions(oldMethod, newMethod, oldAST, newAST)
					fileChanges[name] = changes
					fmt.Printf("Added modified method: %s\n", name)
				}
			}
		}

		if len(fileChanges) > 0 {
			fmt.Printf("Added %d changes for file %s\n", len(fileChanges), goFile)
			granularChanges[goFile] = fileChanges
		}
	}

	// Write the results to a JSON file
	if len(granularChanges) > 0 {
		fmt.Printf("Found granular changes in %d files\n", len(granularChanges))
		granularJSON, err := json.MarshalIndent(granularChanges, "", "  ")
		if err != nil {
			fmt.Printf("Error marshaling granular changes: %v\n", err)
			return
		}

		granularPath := filepath.Join(outputPath, "function_changes_granular.json")
		if err := ioutil.WriteFile(granularPath, granularJSON, 0644); err != nil {
			fmt.Printf("Error writing granular changes file: %v\n", err)
		} else {
			fmt.Printf("Wrote granular function changes to %s\n", granularPath)
		}
	} else {
		fmt.Println("No granular changes found in any files")

		// Write an empty JSON object to the file
		emptyJSON := []byte("{}")
		granularPath := filepath.Join(outputPath, "function_changes_granular.json")
		if err := ioutil.WriteFile(granularPath, emptyJSON, 0644); err != nil {
			fmt.Printf("Error writing empty granular changes file: %v\n", err)
		} else {
			fmt.Printf("Wrote empty granular changes file to %s\n", granularPath)
		}
	}
}

// compareCalledFunctions analyzes the detailed changes between two function declarations
func compareCalledFunctions(oldFunc, newFunc *ast.FuncDecl, oldAST, newAST FileASTData) CalledFunctionChanges {
	oldCalls := extractFunctionCalls(oldFunc)
	newCalls := extractFunctionCalls(newFunc)

	// Find added and removed function calls
	var addedFunctions []string
	for _, call := range newCalls {
		found := false
		for _, oldCall := range oldCalls {
			if call == oldCall {
				found = true
				break
			}
		}
		if !found {
			addedFunctions = append(addedFunctions, call)
		}
	}

	var removedFunctions []string
	for _, call := range oldCalls {
		found := false
		for _, newCall := range newCalls {
			if call == newCall {
				found = true
				break
			}
		}
		if !found {
			removedFunctions = append(removedFunctions, call)
		}
	}

	// Extract literals
	oldLiterals := extractLiterals(oldFunc)
	newLiterals := extractLiterals(newFunc)

	// Find added and removed literals
	var addedLiterals []TypedLiteral
	for _, lit := range newLiterals {
		found := false
		for _, oldLit := range oldLiterals {
			if lit.Type == oldLit.Type && lit.Value == oldLit.Value {
				found = true
				break
			}
		}
		if !found {
			addedLiterals = append(addedLiterals, lit)
		}
	}

	var removedLiterals []TypedLiteral
	for _, lit := range oldLiterals {
		found := false
		for _, newLit := range newLiterals {
			if lit.Type == newLit.Type && lit.Value == newLit.Value {
				found = true
				break
			}
		}
		if !found {
			removedLiterals = append(removedLiterals, lit)
		}
	}

	// Create the result
	result := CalledFunctionChanges{
		AddedFunctions:    removeDuplicates(removedFunctions),
		RemovedFunctions:  removeDuplicates(addedFunctions),
		AddedLiterals:     removedLiterals,
		RemovedLiterals:   addedLiterals,
		OldFunctionSrcLoc: getSourceLocation(oldFunc, oldAST),
		NewFunctionSrcLoc: getSourceLocation(newFunc, newAST),
	}

	// Log the changes found for debugging
	if len(result.AddedFunctions) > 0 || len(result.RemovedFunctions) > 0 ||
		len(result.AddedLiterals) > 0 || len(result.RemovedLiterals) > 0 {
		fmt.Printf("  - Function changes: +%d calls, -%d calls, +%d literals, -%d literals\n",
			len(result.AddedFunctions), len(result.RemovedFunctions),
			len(result.AddedLiterals), len(result.RemovedLiterals))
	}

	return result
}

// extractFunctionCalls extracts all function calls from a function declaration
func extractFunctionCalls(funcDecl *ast.FuncDecl) []string {
	var calls []string

	// Create a visitor that will find all function calls
	visitor := &callVisitor{calls: &calls}

	// Visit all nodes in the function body
	if funcDecl.Body != nil {
		ast.Walk(visitor, funcDecl.Body)
	}

	return calls
}

func (v *callVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}

	switch n := node.(type) {
	case *ast.CallExpr:
		// Extract function name if possible
		switch fn := n.Fun.(type) {
		case *ast.Ident:
			*v.calls = append(*v.calls, fn.Name)
		case *ast.SelectorExpr:
			if x, ok := fn.X.(*ast.Ident); ok {
				*v.calls = append(*v.calls, x.Name+"."+fn.Sel.Name)
			}
		}
	}

	return v
}

// extractLiterals extracts all literals from a function declaration
func extractLiterals(funcDecl *ast.FuncDecl) []TypedLiteral {
	var literals []TypedLiteral

	// Create a visitor that will find all literals
	visitor := &literalVisitor{literals: &literals}

	// Visit all nodes in the function body
	if funcDecl.Body != nil {
		ast.Walk(visitor, funcDecl.Body)
	}

	return literals
}

func (v *literalVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return nil
	}

	switch n := node.(type) {
	case *ast.BasicLit:
		// Basic literals: string, int, float, etc.
		*v.literals = append(*v.literals, TypedLiteral{
			Type:  n.Kind.String(),
			Value: n.Value,
		})
	case *ast.CompositeLit:
		// Composite literals like structs, arrays, etc.
		if n.Type != nil {
			var typeStr string

			// Try to extract the type name
			switch t := n.Type.(type) {
			case *ast.Ident:
				typeStr = "CompositeLit:" + t.Name
			case *ast.ArrayType:
				typeStr = "CompositeLit:Array"
			case *ast.MapType:
				typeStr = "CompositeLit:Map"
			case *ast.StructType:
				typeStr = "CompositeLit:Struct"
			default:
				typeStr = "CompositeLit:Other"
			}

			*v.literals = append(*v.literals, TypedLiteral{
				Type:  typeStr,
				Value: "composite-literal",
			})
		}
	}

	return v
}

// removeDuplicates removes duplicate strings from a slice
func removeDuplicates(strings []string) []string {
	encountered := map[string]bool{}
	result := []string{}

	for _, str := range strings {
		if !encountered[str] {
			encountered[str] = true
			result = append(result, str)
		}
	}

	return result
}

// Helper function to create an empty FileASTData struct
func createEmptyFileASTData() FileASTData {
	return FileASTData{
		Functions:  make(map[string]*ast.FuncDecl),
		Types:      make(map[string]*ast.TypeSpec),
		Interfaces: make(map[string]*ast.TypeSpec),
		Methods:    make(map[string]*ast.FuncDecl),
		FileSet:    token.NewFileSet(),
	}
}

package main

import (
	"go/ast"
	"go/token"
)

// SourceLocation captures position information of a declaration
type SourceLocation struct {
	StartLine int    `json:"startLine"`
	StartCol  int    `json:"startCol"`
	EndLine   int    `json:"endLine"`
	EndCol    int    `json:"endCol"`
	FileName  string `json:"fileName"`
}

// TypedLiteral represents a literal value with its type
type TypedLiteral struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// CalledFunctionChanges captures the granular changes in function calls
type CalledFunctionChanges struct {
	AddedFunctions    []string       `json:"added_functions"`
	RemovedFunctions  []string       `json:"removed_functions"`
	AddedLiterals     []TypedLiteral `json:"added_literals"`
	RemovedLiterals   []TypedLiteral `json:"removed_literals"`
	OldFunctionSrcLoc SourceLocation `json:"old_function_src_loc"`
	NewFunctionSrcLoc SourceLocation `json:"new_function_src_loc"`
}

// NamedCode represents a named code entity with its source
type NamedCode struct {
	Name string `json:"name"`
	Code string `json:"code"`
}

// ModifiedCode represents a code entity that has been modified
type ModifiedCode struct {
	Name    string `json:"name"`
	OldCode string `json:"oldCode"`
	NewCode string `json:"newCode"`
}

// DetailedChanges captures all types of declarations that can change
type DetailedChanges struct {
	ModuleName         string      `json:"moduleName"`
	AddedFunctions     [][]string `json:"addedFunctions"`
	ModifiedFunctions  [][]string  `json:"modifiedFunctions"`
	DeletedFunctions   [][]string `json:"deletedFunctions"`
	AddedTypes         [][]string `json:"addedTypes"`
	ModifiedTypes      [][]string  `json:"modifiedTypes"`
	DeletedTypes       [][]string `json:"deletedTypes"`
	AddedInterfaces    [][]string `json:"addedInterfaces"`
	ModifiedInterfaces [][]string  `json:"modifiedInterfaces"`
	DeletedInterfaces  [][]string `json:"deletedInterfaces"`
	AddedMethods       [][]string `json:"addedMethods"`
	ModifiedMethods    [][]string  `json:"modifiedMethods"`
	DeletedMethods     [][]string `json:"deletedMethods"`
}

func (dc DetailedChanges) HasChanges() bool {
	return len(dc.AddedFunctions) > 0 ||
		len(dc.ModifiedFunctions) > 0 ||
		len(dc.DeletedFunctions) > 0 ||
		len(dc.AddedTypes) > 0 ||
		len(dc.ModifiedTypes) > 0 ||
		len(dc.DeletedTypes) > 0 ||
		len(dc.AddedInterfaces) > 0 ||
		len(dc.ModifiedInterfaces) > 0 ||
		len(dc.DeletedInterfaces) > 0 ||
		len(dc.AddedMethods) > 0 ||
		len(dc.ModifiedMethods) > 0 ||
		len(dc.DeletedMethods) > 0
}

// FileASTData stores AST information for a Go file
type FileASTData struct {
	Functions   map[string]*ast.FuncDecl // name -> AST node
	Types       map[string]*ast.TypeSpec // name -> AST node
	Interfaces  map[string]*ast.TypeSpec // name -> AST node
	Methods     map[string]*ast.FuncDecl // receiverType.methodName -> AST node
	FileContent []byte
	FileSet     *token.FileSet
}

// callVisitor implements the ast.Visitor interface to find function calls
type callVisitor struct {
	calls *[]string
}

// literalVisitor implements the ast.Visitor interface to find literals
type literalVisitor struct {
	literals *[]TypedLiteral
}

package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"os/exec"
	"path/filepath"
)

// compareASTs compares two ASTs and returns the differences
func compareASTs(oldAST, newAST FileASTData, packageName, filePath string, isNewFile, isRemovedFile bool) DetailedChanges {
	changes := DetailedChanges{
		ModuleName: filePath,
	}

	// Handle special cases for new or removed files
	if isNewFile {
		// For new files, all elements are considered "added"
		// Extract all functions from the new AST
		for name, funcDecl := range newAST.Functions {
			changes.AddedFunctions = append(changes.AddedFunctions, []string{name, getSourceCode(funcDecl, newAST)})
		}

		// Extract all types from the new AST
		for name, typeSpec := range newAST.Types {
			changes.AddedTypes = append(changes.AddedTypes, []string{name, getSourceCode(typeSpec, newAST)})
		}

		// Extract all interfaces from the new AST
		for name, interfaceSpec := range newAST.Interfaces {
			changes.AddedInterfaces = append(changes.AddedInterfaces, []string{name, getSourceCode(interfaceSpec, newAST)})
		}

		// Extract all methods from the new AST
		for name, methodDecl := range newAST.Methods {
			changes.AddedMethods = append(changes.AddedMethods, []string{name, getSourceCode(methodDecl, newAST)})
		}

		return changes
	}

	if isRemovedFile {
		// For removed files, all elements are considered "deleted"
		// Extract all functions from the old AST
		for name, funcDecl := range oldAST.Functions {
			changes.DeletedFunctions = append(changes.DeletedFunctions, []string{name, getSourceCode(funcDecl, oldAST)})
		}

		// Extract all types from the old AST
		for name, typeSpec := range oldAST.Types {
			changes.DeletedTypes = append(changes.DeletedTypes, []string{name, getSourceCode(typeSpec, oldAST)})
		}

		// Extract all interfaces from the old AST
		for name, interfaceSpec := range oldAST.Interfaces {
			changes.DeletedInterfaces = append(changes.DeletedInterfaces, []string{name, getSourceCode(interfaceSpec, oldAST)})
		}

		// Extract all methods from the old AST
		for name, methodDecl := range oldAST.Methods {
			changes.DeletedMethods = append(changes.DeletedMethods, []string{name, getSourceCode(methodDecl, oldAST)})
		}

		return changes
	}

	// Normal case - file exists in both versions
	// Compare functions
	changes.AddedFunctions = findAddedFuncElements(oldAST.Functions, newAST.Functions, newAST)
	changes.ModifiedFunctions = findModifiedFuncElements(oldAST.Functions, newAST.Functions, oldAST, newAST)
	changes.DeletedFunctions = findDeletedFuncElements(oldAST.Functions, newAST.Functions, oldAST)

	// Compare types
	changes.AddedTypes = findAddedTypeElements(oldAST.Types, newAST.Types, newAST)
	changes.ModifiedTypes = findModifiedTypeElements(oldAST.Types, newAST.Types, oldAST, newAST)
	changes.DeletedTypes = findDeletedTypeElements(oldAST.Types, newAST.Types, oldAST)

	// Compare interfaces
	changes.AddedInterfaces = findAddedTypeElements(oldAST.Interfaces, newAST.Interfaces, newAST)
	changes.ModifiedInterfaces = findModifiedTypeElements(oldAST.Interfaces, newAST.Interfaces, oldAST, newAST)
	changes.DeletedInterfaces = findDeletedTypeElements(oldAST.Interfaces, newAST.Interfaces, oldAST)

	// Compare methods
	changes.AddedMethods = findAddedFuncElements(oldAST.Methods, newAST.Methods, newAST)
	changes.ModifiedMethods = findModifiedFuncElements(oldAST.Methods, newAST.Methods, oldAST, newAST)
	changes.DeletedMethods = findDeletedFuncElements(oldAST.Methods, newAST.Methods, oldAST)

	return changes
}

// findAddedFuncElements finds elements present in new but not in old (for function decls)
func findAddedFuncElements(oldMap map[string]*ast.FuncDecl, newMap map[string]*ast.FuncDecl, newData FileASTData) [][]string {
	var added [][]string

	for name, newNode := range newMap {
		if _, exists := oldMap[name]; !exists {
			added = append(added, []string{name, getSourceCode(newNode, newData)})
		}
	}

	return added
}

// findModifiedFuncElements compares AST structures instead of code strings
func findModifiedFuncElements(oldMap map[string]*ast.FuncDecl, newMap map[string]*ast.FuncDecl, oldData, newData FileASTData) [][]string {
	var modified [][]string

	for name, oldNode := range oldMap {
		if newNode, exists := newMap[name]; exists {
			oldCode := formatNode(oldNode, oldData.FileSet)
			newCode := formatNode(newNode, newData.FileSet)
			if oldCode != newCode {
				modified = append(modified, []string{name, oldCode, newCode})
			}
		}
	}
	return modified
}

