// Process all Go files with minimized Git checkouts
func processGoFiles(goFiles []string, localRepoPath, branchName, currentCommit string, newFileMap, deletedFileMap map[string]bool) []DetailedChanges {
	var allChanges []DetailedChanges

	// Map to store ASTs from both commits
	branchASTs := make(map[string]FileASTData)
	currentASTs := make(map[string]FileASTData)

	// Step 1: Checkout branch commit and extract ASTs for all files
	checkoutCmd := exec.Command("git", "checkout", branchName)
	checkoutCmd.Dir = localRepoPath
	branchOutput, err := checkoutCmd.CombinedOutput()
	if err != nil {
		fmt.Printf("Error checking out branch %s: %v\nOutput: %s\n",
			branchName, err, string(branchOutput))
		return allChanges
	}
	fmt.Printf("Successfully checked out branch %s\n", branchName)

	// Process all files in the branch commit (except new files)
	for _, goFile := range goFiles {
		if !newFileMap[goFile] {
			fullPath := filepath.Join(localRepoPath, goFile)
			ast, err := extractFileAST(fullPath)
			if err != nil {
				fmt.Printf("Error parsing AST for %s in branch: %v\n", goFile, err)
				// Create an empty AST if we couldn't parse the file
				branchASTs[goFile] = createEmptyAST()
			} else {
				branchASTs[goFile] = ast
			}
		}
	}

	// Step 2: Checkout current commit and extract ASTs for all files
	checkoutCmd = exec.Command("git", "checkout", currentCommit)
	checkoutCmd.Dir = localRepoPath
	commitOutput, err := checkoutCmd.CombinedOutput()
	if err != nil {
		fmt.Printf("Error checking out commit %s: %v\nOutput: %s\n",
			currentCommit, err, string(commitOutput))

		// Try alternative checkout method
		checkoutCmd = exec.Command("git", "checkout", currentCommit+"^{commit}")
		checkoutCmd.Dir = localRepoPath
		output, err := checkoutCmd.CombinedOutput()
		if err != nil {
			fmt.Printf("Error checking out commit directly: %v\nOutput: %s\n", err, string(output))
			return allChanges
		}
		fmt.Println("Successfully checked out commit using alternative method.")
	} else {
		fmt.Printf("Successfully checked out commit %s\n", currentCommit)
	}

	// Process all files in the current commit (except deleted files)
	for _, goFile := range goFiles {
		if !deletedFileMap[goFile] {
			fullPath := filepath.Join(localRepoPath, goFile)
			ast, err := extractFileAST(fullPath)
			if err != nil {
				fmt.Printf("Error parsing AST for %s in current commit: %v\n", goFile, err)
				// Create an empty AST if we couldn't parse the file
				currentASTs[goFile] = createEmptyAST()
			} else {
				currentASTs[goFile] = ast
			}
		}
	}

	// Step 3: Compare all ASTs and collect changes
	for _, goFile := range goFiles {
		// Extract package name for the module name
		var packageName string

		if newFileMap[goFile] {
			// For new files, extract package from current commit's AST
			fullPath := filepath.Join(localRepoPath, goFile)
			packageName = extractPackageName(fullPath)
		} else if deletedFileMap[goFile] {
			// For deleted files, we can't reliably get package name from the file
			// Use directory name as fallback
			packageName = filepath.Base(filepath.Dir(goFile))
		} else {
			// For modified files, use current commit's package name
			fullPath := filepath.Join(localRepoPath, goFile)
			packageName = extractPackageName(fullPath)
		}

		// If package name extraction failed, use directory name
		if packageName == "" {
			packageName = filepath.Base(filepath.Dir(goFile))
		}

		// Initialize old and new ASTs
		var oldAST, newAST FileASTData

		if newFileMap[goFile] {
			// For new files: empty old AST, new AST from current commit
			oldAST = createEmptyAST()
			newAST = currentASTs[goFile]
			fmt.Printf("File %s is new\n", goFile)
		} else if deletedFileMap[goFile] {
			// For deleted files: old AST from branch, empty new AST
			oldAST = branchASTs[goFile]
			newAST = createEmptyAST()
			fmt.Printf("File %s has been deleted\n", goFile)
		} else {
			// For modified files: both ASTs
			oldAST = branchASTs[goFile]
			newAST = currentASTs[goFile]
		}

		// Compare ASTs and collect changes
		changes := compareASTs(oldAST, newAST, packageName, goFile, newFileMap[goFile], deletedFileMap[goFile])
		if changes.HasChanges() {
			allChanges = append(allChanges, changes)
		}
	}

	return allChanges
}

func createEmptyAST() FileASTData {
	return FileASTData{
		Functions:  make(map[string]*ast.FuncDecl),
		Types:      make(map[string]*ast.TypeSpec),
		Interfaces: make(map[string]*ast.TypeSpec),
		Methods:    make(map[string]*ast.FuncDecl),
		FileSet:    token.NewFileSet(),
	}
}

