// createOutputFiles writes JSON output files with the changes
func createOutputFiles(allChanges []DetailedChanges, outputPath string) {
	// Create output directory if it doesn't exist
	if err := os.MkdirAll(outputPath, 0755); err != nil {
		fmt.Printf("Error creating output directory: %v\n", err)
		return
	}

	// Write detailed changes to a single file
	allChangesJSON, err := json.MarshalIndent(allChanges, "", "  ")
	if err != nil {
		fmt.Printf("Error marshaling all changes: %v\n", err)
		return
	}

	allChangesPath := filepath.Join(outputPath, "all_code_changes.json")
	if err := ioutil.WriteFile(allChangesPath, allChangesJSON, 0644); err != nil {
		fmt.Printf("Error writing all changes file: %v\n", err)
	}

	// Create separate files for each type of change
	createTypeSpecificFile(allChanges, "function_changes.json",
		func(c DetailedChanges) ([][]string, [][]string, [][]string) {
			return c.AddedFunctions, c.ModifiedFunctions, c.DeletedFunctions
		}, outputPath)

	createTypeSpecificFile(allChanges, "type_changes.json",
		func(c DetailedChanges) ([][]string, [][]string, [][]string) {
			return c.AddedTypes, c.ModifiedTypes, c.DeletedTypes
		}, outputPath)

	createTypeSpecificFile(allChanges, "interface_changes.json",
		func(c DetailedChanges) ([][]string, [][]string, [][]string) {
			return c.AddedInterfaces, c.ModifiedInterfaces, c.DeletedInterfaces
		}, outputPath)

	createTypeSpecificFile(allChanges, "method_changes.json",
		func(c DetailedChanges) ([][]string, [][]string, [][]string) {
			return c.AddedMethods, c.ModifiedMethods, c.DeletedMethods
		}, outputPath)
}

// createTypeSpecificFile creates a file for a specific type of change
func createTypeSpecificFile(
	allChanges []DetailedChanges,
	filename string,
	extractor func(DetailedChanges) ([][]string, [][]string, [][]string),
	outputPath string,
) {
	type TypeSpecificChanges struct {
		Added    []map[string]interface{} `json:"added"`
		Modified []map[string]interface{} `json:"modified"`
		Deleted  []map[string]interface{} `json:"deleted"`
	}

	changes := TypeSpecificChanges{
		Added:    []map[string]interface{}{},
		Modified: []map[string]interface{}{},
		Deleted:  []map[string]interface{}{},
	}

	for _, c := range allChanges {
		added, modified, deleted := extractor(c)

		for _, item := range added {
			changes.Added = append(changes.Added, map[string]interface{}{
				"module": c.ModuleName,
				"name":   item[0],
				"code":   item[1],
			})
		}

		for _, item := range modified {
			changes.Modified = append(changes.Modified,
				map[string]interface{}{
					"module":  c.ModuleName,
					"name":    item[0],
					"oldCode": item[1],
					"newCode": item[2],
				})
		}

		for _, item := range deleted {
			changes.Deleted = append(changes.Deleted, map[string]interface{}{
				"module": c.ModuleName,
				"name":   item[0],
				"code":   item[1],
			})
		}
	}

	changesJSON, err := json.MarshalIndent(changes, "", "  ")
	if err != nil {
		fmt.Printf("Error marshaling %s: %v\n", filename, err)
		return
	}

	filePath := filepath.Join(outputPath, filename)
	if err := ioutil.WriteFile(filePath, changesJSON, 0644); err != nil {
		fmt.Printf("Error writing %s: %v\n", filename, err)
	}
}

package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
)

// extractPackageName gets the package name from a Go file
func extractPackageName(filePath string) string {
	// Create token file set
	fset := token.NewFileSet()

	// Parse file
	f, err := parser.ParseFile(fset, filePath, nil, parser.PackageClauseOnly)
	if err != nil {
		return ""
	}

	return f.Name.Name
}

// formatNode formats an AST node as a string
func formatNode(node ast.Node, fset *token.FileSet) string {
	var buf bytes.Buffer
	if err := format.Node(&buf, fset, node); err != nil {
		return fmt.Sprintf("Error formatting node: %v", err)
	}
	return buf.String()
}

// extractFileAST extracts AST data from a Go file
func extractFileAST(filePath string) (FileASTData, error) {
	// Create token file set
	fset := token.NewFileSet()

	// Initialize the data structure
	data := FileASTData{
		Functions:  make(map[string]*ast.FuncDecl),
		Types:      make(map[string]*ast.TypeSpec),
		Interfaces: make(map[string]*ast.TypeSpec),
		Methods:    make(map[string]*ast.FuncDecl),
		FileSet:    fset,
	}

	// Try to read file contents
	fmt.Printf("Reading file: %s\n", filePath)
	fileContent, err := ioutil.ReadFile(filePath)
	if err != nil {
		// Check if file exists
		if os.IsNotExist(err) {
			fmt.Printf("File does not exist at this commit: %s\n", filePath)
			return data, fmt.Errorf("file not found: %v", err)
		}
		return data, fmt.Errorf("file couldn't be read: %v", err)
	}

	// Format the content
	formatted, err := format.Source(fileContent)
	if err != nil {
		return data,fmt.Errorf("error formatting source: %v", err)
	}

	// Store the file content for later source extraction
	data.FileContent = formatted

	fmt.Printf("File size: %d bytes\n", len(fileContent))

	// Parse file
	f, err := parser.ParseFile(fset, filePath, formatted, parser.ParseComments)
	if err != nil {
		return data, fmt.Errorf("parsing error: %v", err)
	}

	// Extract declarations
	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Recv == nil {
				// Regular function
				data.Functions[d.Name.Name] = d
			} else {
				// Method
				recvType := getReceiverType(d.Recv)
				if recvType != "" {
					data.Methods[recvType+"."+d.Name.Name] = d
				}
			}

		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					// Check if it's an interface
					if _, isInterface := s.Type.(*ast.InterfaceType); isInterface {
						data.Interfaces[s.Name.Name] = s
					} else {
						data.Types[s.Name.Name] = s
					}

					// Log the extracted type for debugging
					fmt.Printf("Extracted type %s from %s\n", s.Name.Name, filePath)
				}
			}
		}
	}

	return data, nil
}

// getReceiverType extracts the receiver type name from a method's receiver field list
func getReceiverType(recv *ast.FieldList) string {
	if recv == nil || len(recv.List) == 0 {
		return ""
	}

	// Handle pointer receivers
	var typeExpr ast.Expr = recv.List[0].Type
	if starExpr, ok := typeExpr.(*ast.StarExpr); ok {
		typeExpr = starExpr.X
	}

	// Get type name
	if ident, ok := typeExpr.(*ast.Ident); ok {
		return ident.Name
	}

	return ""
}

// getSourceCode extracts source code from an AST node
func getSourceCode(node ast.Node, data FileASTData) string {
	if node == nil || data.FileContent == nil || data.FileSet == nil {
		return ""
	}

	startPos := data.FileSet.Position(node.Pos()).Offset
	endPos := data.FileSet.Position(node.End()).Offset

	if startPos >= 0 && endPos <= len(data.FileContent) && startPos <= endPos {
		return string(data.FileContent[startPos:endPos])
	}

	return ""
}

// getSourceLocation extracts location info from an AST node
func getSourceLocation(node ast.Node, data FileASTData) SourceLocation {
	if node == nil || data.FileSet == nil {
		return SourceLocation{
			StartLine: 0,
			StartCol:  0,
			EndLine:   0,
			EndCol:    0,
			FileName:  "<unknown>",
		}
	}

	startPos := data.FileSet.Position(node.Pos())
	endPos := data.FileSet.Position(node.End())

	return SourceLocation{
		StartLine: startPos.Line,
		StartCol:  startPos.Column,
		EndLine:   endPos.Line,
		EndCol:    endPos.Column,
		FileName:  startPos.Filename,
	}
}
